//#region src/caps/lib/meta.js
function pageHead(title, description) {
	const t = `${title} · CAPS`;
	return { meta: [
		{ title: t },
		{
			name: "description",
			content: description
		},
		{
			property: "og:title",
			content: t
		},
		{
			property: "og:description",
			content: description
		},
		{
			property: "og:type",
			content: "website"
		},
		{
			name: "twitter:card",
			content: "summary"
		}
	] };
}
//#endregion
export { pageHead as t };
